INSERT INTO news (id, title, body, media_urls, action_id, created_at, updated_at) VALUES (1, 'Загадочное ограбление в Старом Граде', 'Нови-Сад — Сегодня ранним утром полиция оцепила район Старого Града после того, как поступило сообщение о необычном ограблении, произошедшем минувшей ночью. По предварительной информации, объектом нападения стал не банк или ювелирный магазин, а частная коллекция, находившаяся в старинном доме на одной из узких улочек.
